draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 150);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 70 + 50 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 70 - 50 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 + 30 - 20 * Math.sin(t), H/2 + 200);
  ctx.stroke();

  // eyes
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 15, H/2 - 15, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 15, H/2 - 15, 10, 0, 2 * Math.PI);
  ctx.fill();

  // refusal gesture
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 100 + 20 * Math.cos(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 100 + 20 * Math.cos(t), H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
